"""Standard-library extraction helpers for ouch-style archives."""
import bz2
import gzip
import io
import lzma
import os
import pathlib
import sys
import tarfile
import zipfile


ALIASES = {
    "tgz": ["tar", "gz"], "tbz": ["tar", "bz2"], "tbz2": ["tar", "bz2"],
    "txz": ["tar", "xz"], "tlzma": ["tar", "lzma"], "tzst": ["tar", "zst"],
    "tlz": ["tar", "lz"], "tlz4": ["tar", "lz4"], "tsz": ["tar", "sz"],
    "cbt": ["tar"], "cbz": ["zip"], "epub": ["zip"], "cb7": ["7z"], "cbr": ["rar"],
}
STREAMS = {"gz", "bz", "bz2", "xz", "lzma"}
KNOWN = STREAMS | {"tar", "zip", "7z", "sz", "zst", "lz", "lzip", "bz3", "lz4", "rar", "br", *ALIASES}


def formats_for(path, override=None):
    if override:
        values = [x.lower().lstrip(".") for x in override.split(".") if x]
    else:
        suffixes = pathlib.Path(os.fspath(path)).name.split(".")[1:]
        values = []
        for suffix in reversed(suffixes):
            if suffix not in KNOWN:
                break
            values.append(suffix)
        values.reverse()
    if len(values) == 1 and values[0] in ALIASES:
        values = ALIASES[values[0]][:]
    return values


def output_name(path, formats=None):
    if os.fspath(path) == "-":
        return "ouch-output"
    name = os.path.basename(os.fspath(path))
    values = formats if formats is not None else formats_for(path)
    parts = name.split(".")
    raw_suffix = parts[-1] if len(parts) > 1 else ""
    strip_count = 1 if raw_suffix in ALIASES else len(values)
    if strip_count and len(parts) > strip_count:
        name = ".".join(parts[:-strip_count])
    if not name:
        name = "ouch-output"
    return name


def signature_formats(path):
    """Infer common formats from their file signatures when suffixes are unknown."""
    try:
        with open(path, "rb") as f:
            head = f.read(512)
    except OSError:
        return []
    if head.startswith(b"\x1f\x8b"): return ["gz"]
    if head.startswith(b"BZh"): return ["bz2"]
    if head.startswith(b"\xfd7zXZ\x00"): return ["xz"]
    if head.startswith((b"PK\x03\x04", b"PK\x05\x06", b"PK\x07\x08")): return ["zip"]
    if len(head) >= 262 and head[257:262] == b"ustar": return ["tar"]
    if head.startswith(b"\x04\x22\x4d\x18"): return ["lz4"]
    if head.startswith(b"\x28\xb5\x2f\xfd"): return ["zst"]
    if head.startswith(b"7z\xbc\xaf\x27\x1c"): return ["7z"]
    return []


def _safe_target(root, name):
    # Normalize absolute archive paths to the destination root, but reject
    # parent traversal so entries cannot escape that root.
    name = name.replace("\\", "/").lstrip("/")
    if len(name) >= 2 and name[1] == ':':
        name = name[2:].lstrip('/')
    p = pathlib.PurePosixPath(name)
    if ".." in p.parts:
        return None
    target = os.path.abspath(os.path.join(root, *p.parts))
    if os.path.commonpath((os.path.abspath(root), target)) != os.path.abspath(root):
        return None
    return target


def _safe_link(root, link_path, link_name):
    """Return a relative link target only when its resolution stays in root."""
    link_name = link_name.replace("\\", "/")
    if link_name.startswith("/"):
        return None
    parent = os.path.dirname(link_path)
    resolved = os.path.abspath(os.path.join(parent, link_name))
    base = os.path.abspath(root)
    if os.path.commonpath((base, resolved)) != base:
        return None
    return link_name


def _unpack_zip(zf, root):
    count = 0
    for info in zf.infolist():
        target = _safe_target(root, info.filename)
        if target is None:
            continue
        if info.is_dir():
            os.makedirs(target, exist_ok=True)
        elif (info.external_attr >> 16) & 0o170000 == 0o120000:
            link_text = zf.read(info).decode("utf-8", "surrogateescape")
            safe_link = _safe_link(root, target, link_text)
            if safe_link is not None:
                os.makedirs(os.path.dirname(target), exist_ok=True)
                if os.path.lexists(target):
                    if os.path.isdir(target) and not os.path.islink(target):
                        continue
                    os.unlink(target)
                os.symlink(safe_link, target)
        else:
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with zf.open(info) as src, open(target, "wb") as dst:
                while True:
                    block = src.read(1024 * 1024)
                    if not block:
                        break
                    dst.write(block)
        count += 1
    return count


def _unpack_tar(tf, root):
    count = 0
    for member in tf.getmembers():
        target = _safe_target(root, member.name)
        if target is None:
            count += 1
            continue
        if member.isdir():
            os.makedirs(target, exist_ok=True)
        elif member.isfile():
            os.makedirs(os.path.dirname(target), exist_ok=True)
            src = tf.extractfile(member)
            if src:
                with src, open(target, "wb") as dst:
                    while True:
                        block = src.read(1024 * 1024)
                        if not block:
                            break
                        dst.write(block)
                os.chmod(target, member.mode & 0o777)
        elif member.issym():
            safe_link = _safe_link(root, target, member.linkname)
            if safe_link is not None:
                os.makedirs(os.path.dirname(target), exist_ok=True)
                if os.path.lexists(target):
                    if os.path.isdir(target) and not os.path.islink(target):
                        continue
                    os.unlink(target)
                os.symlink(safe_link, target)
        elif member.islnk():
            # TAR hard-link names are rooted at the archive destination.
            link_target = _safe_target(root, member.linkname)
            if link_target is not None and os.path.exists(link_target):
                os.makedirs(os.path.dirname(target), exist_ok=True)
                if not os.path.lexists(target):
                    os.link(link_target, target)
            else:
                continue
        else:
            continue
        count += 1
    return count


def decompress_file(path, output_dir=None, here=False, format=None, signature_fallback=False):
    """Extract a supported archive; return (destination, extracted-entry-count).

    ZIP/TAR archives are extracted into a basename directory by default. A
    single stream-compressed file is written beside the source under its
    decompressed basename. `output_dir` overrides either destination.
    """
    path = os.fspath(path)
    formats = formats_for(path, format)
    if not formats:
        raise ValueError("unsupported extension")
    destination = "." if here else (os.fspath(output_dir) if output_dir else None)

    stdin_data = sys.stdin.buffer.read() if path == "-" else None
    direct_zip = bool(formats and formats[-1] == "zip")
    zip_input = io.BytesIO(stdin_data) if stdin_data is not None and direct_zip else path
    if (path != "-" and ((format is None and zipfile.is_zipfile(path)) or direct_zip)) or (path == "-" and direct_zip):
        if destination is None:
            if signature_fallback:
                original = os.path.basename(path)
                destination = (original.rsplit(".", 1)[0] if "." in original else original) + "-output"
            else:
                destination = os.path.basename(path) if format and path != "-" else output_name(path, formats)
        with zipfile.ZipFile(zip_input) as zf:
            os.makedirs(destination, exist_ok=True)
            return destination, _unpack_zip(zf, destination)

    # Decode outer stream layers. This also recognizes chained TAR suffixes.
    data = stdin_data if stdin_data is not None else open(path, "rb").read()
    remaining = formats[:]
    while remaining and remaining[-1] in STREAMS:
        fmt = remaining.pop()
        if fmt == "gz":
            if not data:
                raise EOFError("unexpected end of file")
            data = gzip.decompress(data)
        elif fmt in ("bz", "bz2"):
            data = bz2.decompress(data)
        else:
            data = lzma.decompress(data)
    if remaining and remaining[-1] == "zip":
        if destination is None:
            destination = os.path.basename(path) if format and path != "-" else output_name(path, formats)
        os.makedirs(destination, exist_ok=True)
        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            return destination, _unpack_zip(zf, destination)
    if remaining and remaining[-1] == "tar":
        if destination is None:
            if signature_fallback:
                original = os.path.basename(path)
                destination = (original.rsplit(".", 1)[0] if "." in original else original) + "-output"
            else:
                destination = os.path.basename(path) if format and path != "-" else output_name(path, formats)
        with tarfile.open(fileobj=io.BytesIO(data), mode="r:") as tf:
            os.makedirs(destination, exist_ok=True)
            return destination, _unpack_tar(tf, destination)

    if formats[-1] in STREAMS:
        if destination is None:
            destination = "." if here or path == "-" else (os.path.dirname(path) or ".")
        os.makedirs(destination, exist_ok=True)
        basename = os.path.basename(path) if format and path != "-" else output_name(path, formats)
        if signature_fallback:
            original = os.path.basename(path)
            basename = original.rsplit(".", 1)[0] + "-output" if "." in original else original + "-output"
        target = os.path.join(destination, basename)
        with open(target, "wb") as out:
            out.write(data)
        return destination, 1
    raise ValueError("unsupported archive format")
